SELECT u.id, u.username, u.name, u.phone, u.email, u.role, u.create_time
FROM user u
WHERE u.campus_id = #{campusId}
AND u.deleted = 0

    AND u.role = #{role}

ORDER BY u.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM user u
WHERE u.campus_id = #{campusId}
AND u.deleted = 0

    AND u.role = #{role}
